"""Prediccion exacta para dos paredes y un viajero interior."""
from math import isqrt


def _cycle(left, width, steps):
    # Estado de referencia: a en left+1 y paredes separadas por width.
    # k viajes completos consumen k*k + (2*width-3)*k pasos.
    b = 2 * width - 3
    k = (isqrt(b * b + 4 * steps) - b) // 2
    t = steps - k * (k + b)
    width += k
    right = left + width
    if t <= width - 2:
        return {left: 'd', right: 'd', left + 1 + t: 'ab'[t & 1]}
    if t == width - 1:
        return {left: 'd', right: 'e', right - 1: 'c'}
    return {left: 'd', right + 1: 'd', right + width - 2 - t: 'c'}


def predict(start, steps):
    if steps == 0:
        return dict(start)
    left, pos, right = sorted(start)
    symbol = start[pos]
    width = right - left
    offset = pos - left

    if symbol == 'c':
        # Una c pegada a la pared derecha la elimina al primer paso.
        lost_right = offset == width - 1
        if steps < offset:
            result = {left: 'd', pos - steps: 'c'}
            if not lost_right:
                result[right] = 'd'
            return result
        steps -= offset
        if lost_right:
            return {left: 'd', left + 1 + steps: 'ab'[steps & 1]}
        return _cycle(left, width, steps)

    # a/b avanzan a la derecha alternando su letra.
    lost_left = symbol == 'b' and offset == 1
    hit = right - pos
    if steps < hit:
        letter = symbol if not (steps & 1) else ('b' if symbol == 'a' else 'a')
        result = {right: 'd', pos + steps: letter}
        if not lost_left:
            result[left] = 'd'
        return result
    if steps == hit:
        result = {right: 'e', right - 1: 'c'}
        if not lost_left:
            result[left] = 'd'
        return result

    if lost_left:
        return {right + 1: 'd', right - 1 - (steps - hit): 'c'}

    # Tras el rebote derecho, c vuelve hasta la izquierda y se hace a.
    home = hit + width - 1
    if steps < home:
        return {left: 'd', right + 1: 'd', right - 1 - (steps - hit): 'c'}
    return _cycle(left, width + 1, steps - home)

